import os,re
from collections import Counter
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); inp,out=G['Demo pair 1 input'],G['Demo pair 1 output']

def transform(grid):
    h,w=len(grid),len(grid[0])
    g=[row[:] for row in grid]
    cnt=Counter(v for row in grid for v in row)
    block=cnt.most_common(1)[0][0]
    obs=next((c for c in cnt if c not in (0,block)), None)
    rows_=sorted({r for r in range(h) for c in range(w) if grid[r][c]==block})
    cols_=sorted({c for r in range(h) for c in range(w) if grid[r][c]==block})
    for r in rows_:
        cs=[c for c in range(w) if grid[r][c]==block]
        L,R=min(cs),max(cs)
        if obs is None or not any(grid[r][c]==obs for c in range(0,L)):
            for c in range(0,L): g[r][c]=block
        if obs is None or not any(grid[r][c]==obs for c in range(R+1,w)):
            for c in range(R+1,w): g[r][c]=block
    for c in cols_:
        rs=[r for r in range(h) if grid[r][c]==block]
        T,B=min(rs),max(rs)
        if obs is None or not any(grid[r][c]==obs for r in range(0,T)):
            for r in range(0,T): g[r][c]=block
        if obs is None or not any(grid[r][c]==obs for r in range(B+1,h)):
            for r in range(B+1,h): g[r][c]=block
    return g

